DO $$
DECLARE
  n integer;
  p integer;
  a integer;
  orig_err text;
  new_err text;
BEGIN
  TRUNCATE performance, member_attendance;
  INSERT INTO performance SELECT * FROM backup_performance;
  INSERT INTO member_attendance SELECT * FROM backup_member_attendance;
  DROP TABLE IF EXISTS snap_perf;
  DROP TABLE IF EXISTS snap_ma;
  CREATE TABLE snap_perf AS TABLE performance;
  CREATE TABLE snap_ma AS TABLE member_attendance;

  FOR n IN SELECT * FROM (VALUES (-5),(0),(1),(4),(9),(NULL::integer)) AS t(v) LOOP
    FOR p IN SELECT * FROM (VALUES (-3),(0),(5),(50),(NULL::integer)) AS t(v) LOOP
      FOR a IN SELECT * FROM (VALUES (NULL::integer),(165),(1820),(1878),(2000),(9999)) AS t(v) LOOP
        -- restore base
        TRUNCATE performance, member_attendance;
        INSERT INTO performance SELECT * FROM backup_performance;
        INSERT INTO member_attendance SELECT * FROM backup_member_attendance;

        orig_err := NULL;
        BEGIN
          CALL sp_orig(n,p,a,'x');
        EXCEPTION WHEN OTHERS THEN
          orig_err := SQLSTATE || ':' || SQLERRM;
        END;

        TRUNCATE snap_perf, snap_ma;
        INSERT INTO snap_perf SELECT * FROM performance;
        INSERT INTO snap_ma SELECT * FROM member_attendance;

        -- restore base again
        TRUNCATE performance, member_attendance;
        INSERT INTO performance SELECT * FROM backup_performance;
        INSERT INTO member_attendance SELECT * FROM backup_member_attendance;

        new_err := NULL;
        BEGIN
          CALL sp_new(n,p,a,'x');
        EXCEPTION WHEN OTHERS THEN
          new_err := SQLSTATE || ':' || SQLERRM;
        END;

        IF (orig_err IS NULL) <> (new_err IS NULL) THEN
          RAISE EXCEPTION 'error mismatch n=% p=% a=% orig=% new=%', n, p, a, orig_err, new_err;
        END IF;
        IF orig_err IS NULL THEN
          IF EXISTS (SELECT * FROM ((SELECT * FROM performance EXCEPT ALL SELECT * FROM snap_perf) UNION ALL (SELECT * FROM snap_perf EXCEPT ALL SELECT * FROM performance)) x) THEN
            RAISE EXCEPTION 'perf mismatch n=% p=% a=%', n, p, a;
          END IF;
          IF EXISTS (SELECT * FROM ((SELECT * FROM member_attendance EXCEPT ALL SELECT * FROM snap_ma) UNION ALL (SELECT * FROM snap_ma EXCEPT ALL SELECT * FROM member_attendance)) x) THEN
            RAISE EXCEPTION 'ma mismatch n=% p=% a=%', n, p, a;
          END IF;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'branch1 ok';
END $$;

